></div></div>\n<!-- /wp:ogb/column -->\n\n<!-- wp:ogb/column {\"blockId\":\"0f508a15\",\"colWidth\":\"33.33\"} -->\n<div class=\"ogb-block ogb-column ogb-column-0f508a15\"><div class=\"ogb-column-container\"><!-- wp:html -->\n<div class=\"swiper mySwiper\">\n  <div class=\"swiper-wrapper\">\n    <!-- Slides -->\n    <div class=\"swiper-slide\">\n      <img src=\"http://localhost/homedesk/wp-content/uploads/2025/05/homedesk-assis-debout-2-1024x1024.jpg\" loading=\"lazy\" alt=\"Image 1\">\n    </div>\n    <div class=\"swiper-slide\">\n      <img src=\"http://localhost/homedesk/wp-content/uploads/2025/05/homedesk-assis-debout-2-1024x1024.jpg\" loading=\"lazy\" alt=\"Image 2\">\n    </div>\n    <div class=\"swiper-slide\">\n      <img src=\"http://localhost/homedesk/wp-content/uploads/2025/05/homedesk-assis-debout-2-1024x1024.jpg\" loading=\"lazy\" alt=\"Image 3\">\n    </div>\n    <div class=\"swiper-slide\">\n      <img src=\"http://localhost/homedesk/wp-content/uploads/2025/05/homedesk-assis-debout-2-1024x1024.jpg\" loading=\"lazy\" alt=\"Image 4\">\n    </div>\n    <div class=\"swiper-slide\">\n      <img src=\"http://localhost/homedesk/wp-content/uploads/2025/05/homedesk-assis-debout-2-1024x1024.jpg\" loading=\"lazy\" alt=\"Image 5\">\n    </div>\n  </div>\n  \n  <!-- Navigation buttons -->\n  <div class=\"swiper-button-next\"></div>\n  <div class=\"swiper-button-prev\"></div>\n  \n  <!-- Pagination -->\n  <div class=\"swiper-pagination\"></div>\n</div>\n<!-- /wp:html --></div></div>\n<!-- /wp:ogb/column --></div></div>\n<!-- /wp:ogb/columns --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"metadata\":{\"categories\":[\"about\"],\"patternName\":\"woocommerce-blocks/content-right-with-image-left\",\"name\":\"Content right with image left\"},\"className\":\"alignfull\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"calc( 0.5 * var(\\u002d\\u002dwp\\u002d\\u002dstyle\\u002d\\u002droot\\u002d\\u002dpadding-right, var(\\u002d\\u002dwp\\u002d\\u002dcustom\\u002d\\u002dga