(42, 'woocommerce-WCSubscriptions-June-2023-updated-needed', 'marketing', 'en_US', 'Action required: Security update of WooCommerce Subscriptions', '<strong>Your store requires a security update for the WooCommerce Subscriptions plugin</strong>. Please update the WooCommerce Subscriptions plugin immediately to address a potential vulnerability.', '{}', 'pending', 'woocommerce.com', '2025-02-27 15:18:57', NULL, 0, 'plain', '', 0, 0, 'info'),
(43, 'woocommerce-WCReturnsWarranty-June-2023-updated-needed', 'update', 'en_US', 'Action required: Security update of WooCommerce Returns and Warranty Requests extension', '<strong>Your store requires a security update for the Returns and Warranty Requests extension</strong>.  Please update to the latest version of the WooCommerce Returns and Warranty Requests extension immediately to address a potential vulnerability discovered on May 31.', '{}', 'pending', 'woocommerce.com', '2025-02-27 15:18:57', NULL, 0, 'plain', '', 0, 0, 'info'),
(44, 'woocommerce-WCOPC-June-2023-updated-needed', 'update', 'en_US', 'Action required: Security update of WooCommerce One Page Checkout', '<strong>Your shop requires a security update to address a vulnerability in the WooCommerce One Page Checkout extension</strong>. The fix for this vulnerability was released for this extension on June 13th. Please update immediately.', '{}', 'pending', 'woocommerce.com', '2025-02-27 15:18:57', NULL, 0, 'plain', '', 0, 0, 'info'),
(45, 'woocommerce-WCGC-July-2023-update-needed', 'update', 'en_US', 'Action required: Security update of WooCommerce GoCardless Extension', '<strong>Your shop requires a security update to address a vulnerability in the WooCommerce GoCardless extension</strong>. The fix for this vulnerability was released on July 4th. Please update immediately.', '{}', 'pending', 'woocommerce.com', '2025-02-27 15:18:57', NULL, 0, 'plain', '', 0, 0, 'info'),
(46, 'woocommerce-shipping-fedex-api-outage-2023-07-16', 'warning', 'en_US', 'Scheduled FedEx API outage — July 2023', 'On July 16 there will be a full outage of the FedEx API from 04:00 to 08:00 AM UTC. Due to planned maintenance by FedEx, you\'ll be unable to provide FedEx shipping rates during this time. Follow the link below for more information and recommendations on how to minimize impact.', '{}', 'pending', 'woocommerce.com', '2025-02-27 15:18:57', NULL, 0, 'plain', '', 0, 0, 'info'),
(47, 'wcship-2023-07-hazmat-update-needed', 'update', 'en_US', 'Action required: USPS HAZMAT compliance update for WooCommerce Shipping & Tax extension', '<strong>Your store requires an update for the WooCommerce Shipping extension</strong>. Please update to the latest version of the WooCommerce Shipping &amp; Tax extension immediately to ensure compliance with new USPS HAZMAT rules currently in effect.', '{}', 'pending', 'woocommerce.com', '2025-02-27 15:18:57', NULL, 0, 'plain', '', 0, 0, 'info'),
(48, 'woocommerce-WCStripe-Aug-2023-update-needed', 'update', 'en_US', 'Action required: Security update for WooCommerce Stripe plugin', '<strong>Your shop requires an important security update for the  WooCommerce Stripe plugin</strong>. The fix for this vulnerability was released on July 31. Please update immediately.', '{}', 'pending', 'woocommerce.com', '2025-02-27 15:18:57', NULL, 0, 'plain', '', 0, 0, 'info'),
(49, 'woocommerce-WCStripe-Aug-2023-security-updated', 'update', 'en_US', 'Security update of WooCommerce Stripe plugin', '<strong>Your store has been updated to the latest secure version of the WooCommerce Stripe plugin</strong>. This update was released on July 31.', '{}', 'pending', 'woocommerce.com', '2025-02-27 15:18:57', NULL, 0, 'plain', '', 0, 0, 'info'),
(50, 'woocommerce-WooPayments-Aug-2023-security-updated', 'update', 'en_US', 'Security update of WooPayments (WooCommerce Payments) plugin', '<strong>Your store has been updated to the more secure version of WooPayments (WooCommerce Payments)</strong>. This update was released on July 31.', '{}', 'pending', 'woocommerce.com', '2025-02-27 15:18:57', NULL, 0, 'plain', '', 0, 0, 'info'),
(51, 'avalara_q3-2023_noAvaTax', 'marketing', 'en_US', 'Automatically calculate VAT in real time', 'Take the effort out of determining tax rates and sell confidently across borders with automated tax management from Avalara AvaTax— including built-in VAT calculation when you sell into or across the EU and UK. Save time and stay compliant when you let Avalara do the heavy lifting.', '{}', 'pending', 'woocommerce.com', '2025-02-27 15:18:57', NULL, 0, 'plain', '', 0, 0, 'info'),
(52, 'woocommerce-usermeta-Sept2023-productvendors', 'update', 'en_US', 'Your store requires a security update', '<strong>Your shop needs an update to address a vulnerability in WooCommerce.</strong> The fix was released on Sept 15. Please update WooCommerce to the latest version immediately. <a href=\"https://developer.woocommerce.com/2023/09/16/woocommerce-vulnerability-reintroduced-from-7-0-1/\" />Read our developer update</a> for more information.', '{}', 'pending', 'woocommerce.com', '2025-02-27 15:18:57', NULL, 0, 'plain', '', 0, 0, 'info'),
(53, 'woocommerce-STRIPE-Oct-2023-update-needed', 'update', 'en_US', 'Action required: Security update for WooCommerce Stripe Gateway', '<strong>Your shop requires a security update to address a vulnerability in the WooCommerce Stripe Gateway</strong>. The fix for this vulnerability was released on October 17. Please update immediately.', '{}', 'pending', 'woocommerce.com', '2025-02-27 15:18:57', NULL, 0, 'plain', '', 0, 0, 'info'),
(54, 'amazon-mcf-reviews-2023-12-07', 'marketing', 'en_US', 'Enjoying Amazon MCF for WooCommerce?', 'We\'re Never Settle, the developers behind Amazon MCF for WooCommerce, and would be deeply honored to have your review. Reviews help immensely as other users can learn how MCF can solve their needs too! Not happy or need help? Please reach out for support and we’d love to make things right!', '{}', 'pending', 'woocommerce.com', '2025-02-27 15:18:57', NULL, 0, 'plain', '', 0, 0, 'info'),
(55, 'remove_estimated_deposits_2024', 'marketing', 'en_US', 'Estimated deposits are going away', 'To provide more accurate deposit information and support the expansion of instant deposits, estimated deposit details will no longer be available in WooPayments. We recommend upgrading to the latest version of WooPayments for more detailed balance status information.', '{}', 'pending', 'woocommerce.com', '2025-02-27 15:18:57', NULL, 0, 'plain', '', 0, 0, 'info'),
(56, 'sirt-woo-2024-11-xss-admin', 'update', 'en_US', 'An important update is required for WooCommerce', 'This update addresses a security vulnerability that could allow unauthorized access to administrative privileges on your site. <a href=\"https://developer.woocommerce.com/2024/12/03/woocommerce-9-4-3-and-woocommerce-9-3-4-available-now/\">Learn more</a>.\r\n<br><br>\r\n<strong>Please ensure your site is updated to the latest version to stay secure.</strong>', '{}', 'pending', 'woocommerce.com', '2025-02-27 15:18:57', NULL, 0, 'plain', '', 0, 0, 'info'),
(57, 'woocommerce-analytics-order-attribution-promotions-december-2024', 'marketing', 'en_US', 'Discover what drives your sales', 'Use our powerful <strong>Order Attribution</strong> extension to understand what truly drives your revenue. Track your sales journey, identify your most effective marketing channels, and optimize your sales strategy.', '{}', 'pending', 'woocommerce.com', '2025-02-27 15:18:57', NULL, 0, 'plain', '', 0, 0, 'info'),
(58, 'printful_promo_q1_2025', 'marketing', 'en_US', 'New: sell print-on-demand products, risk-free', 'Expand your product line with Printful, now available in the WooCommerce Marketplace. Sell custom products with no upfront costs or inventory. This trusted supplier prints, packages, and ships for you, so you can focus on growing your store — and your next big idea.', '{}', 'pending', 'woocommerce.com', '2025-02-27 15:18:57', NULL, 0, 'plain', '', 0, 0, 'info'),
(59, 'wc-admin-choosing-a-theme', 'marketing', 'en_US', 'Vous cherchez un thème ?', 'Découvrez les thèmes compatibles avec WooCommerce et choisissez celui qui correspond le mieux à l’image de votre marque et à vos besoins.', '{}', 'unactioned', 'woocommerce-admin', '2025-03-01 12:25:10', NULL, 0, 'plain', '', 0, 0, 'info'),
(60, 'wc-admin-customizing-product-catalog', 'info', 'en_US', 'Comment personnaliser votre catalogue de produits', 'Vous souhaitez soigner l’apparence de vos images et de votre catalogue de produits tout en vous conformant à votre marque. Ce guide contient tous les conseils dont vous avez besoin pour mettre en valeur vos produits dans votre boutique.', '{}', 'unactioned', 'woocommerce-admin', '2025-03-01 12:25:10', NULL, 0, 'plain', '', 0, 0, 'info'),
(61, 'wc-admin-mobile-app', 'info', 'en_US', 'Installer l’application mobile Woo', 'Installez l’application mobile WooCommerce pour gérer les commandes, recevoir des notifications de vente et afficher les statistiques principales où que vous soyez.', '{}', 'unactioned', 'woocommerce-admin', '2025-03-02 11:26:35', NULL, 0, 'plain', '', 0, 0, 'info'),
(62, 'wc-admin-onboarding-payments-reminder', 'info', 'en_US', 'Commencer à accepter les paiements sur votre boutique !', 'Accepter les paiements avec le fournisseur qui vous convient, parmi plus de 100 passerelles de paiement pour WooCommerce.', '{}', 'unactioned', 'woocommerce-admin', '2025-03-15 09:42:31', NULL, 0, 'plain', '', 0, 0, 'info'),
(63, 'wc-admin-usage-tracking-opt-in', 'info', 'en_US', 'Aider WooCommerce à améliorer ses services grâce au suivi de l’utilisation', 'Récupérer les données d’utilisation nous permet d’améliorer WooCommerce. Votre boutique sera prise en compte lors de l’évaluation des nouvelles fonctionnalités et de la qualité d’une mise à jour, ou pour déterminer l’intérêt d’une amélioration. Vous pouvez toujours consulter les <a href=\"http://localhost/homedesk/wp-admin/admin.php?page=wc-settings&#038;tab=advanced&#038;section=woocommerce_com\" target=\"_blank\">Paramètres</a> et choisir d’interrompre le partage des données. <a href=\"https://woocommerce.com/usage-tracking?utm_medium=product\" target=\"_blank\">En savoir plus</a> sur les données que nous collectons.', '{}', 'unactioned', 'woocommerce-admin', '2025-03-15 09:42:32', NULL, 0, 'plain', '', 0, 0, 'info'),
(64, 'wc-admin-woocommerce-payments', 'marketing', 'en_US', 'Découvrez la nouvelle façon de se faire payer', 'Acceptez les cartes bancaires en toute sécurité sur votre site. Gérez les transactions sans quitter votre tableau de bord WordPress. Uniquement avec <strong>WooPayments</strong>.<br><br>En cliquant sur ­« Bien démarrer », vous êtes d’accord avec nos <a href=\"https://wordpress.com/tos/\" target=\"_blank\">conditions d’utilisation</a>', '{}', 'unactioned', 'woocommerce-admin', '2025-03-15 09:42:32', NULL, 0, 'plain', '', 0, 0, 'info'),
(65, 'paypal-braintree-sdk-depreciation-2025-02-20', 'update', 'en_US', 'Update required for your PayPal Braintree extension', 'To continue securely accepting payments, you must update your PayPal Braintree extension to version 3.2.4 or newer before June 30, 2025. Your current extension version will not support payment processing after this date due to an SSL certificate update.', '{}', 'pending', 'woocommerce.com', '2025-03-15 09:42:37', NULL, 0, 'plain', '', 0, 0, 'info'),
(66, 'woo-marketplace-two-year-subscriptions-rin-2025-03-17', 'marketing', 'en_US', 'Save 20% on new two-year subscriptions', 'We’ve introduced 20% off two-year subscriptions for all products* in the WooCommerce Marketplace. Lock in long-term savings and make sure your store never misses a beat. \r\n\r\n*Some exclusions apply. New purchases only.', '{}', 'pending', 'woocommerce.com', '2025-03-24 08:28:34', NULL, 0, 'plain', '', 0, 0, 'info'),
(67, 'viva_wallet_migration_q1_2025', 'update', 'en_US', 'Switch to the new Viva.com Smart Checkout', 'The Viva Wallet extension is no longer being updated and improved. To get the best Viva.com experience, move to the new Smart Checkout. It’s fast, secure, and fully compatible with the latest WooCommerce features.', '{}', 'pending', 'woocommerce.com', '2025-04-06 10:24:35', NULL, 0, 'plain', '', 0, 0, 'info'),
(68, 'stripe_orderstatus_bug_q2_2025', 'update', 'en_US', 'Action Required: Update Order Status Manager', 'Update to the latest Order Status Manager (v1.15.5+) to ensure payments are captured. Your version of WooCommerce Order Status Manager can interfere with order processing for payment gateways (including WooCommerce Stripe Gateway v9.2.0+), which may cause orders to process without capturing payment.', '{}', 'pending', 'woocommerce.com', '2025-04-06 10:24:35', NULL, 0, 'plain', '', 0, 0, 'info'),
(69, 'klaviyo_q2_2025', 'marketing', 'en_US', 'Tailor your marketing with data-driven automation', 'Deliver personalized experiences at scale, simplify your stack, and make your data work for you using Klaviyo’s best-in-class marketing extension for Woo. With advanced segmentation based on actual customer behavior, you can send email and SMS messages that drive revenue and increase loyalty — without adding complexity', '{}', 'pending', 'woocommerce.com', '2025-05-04 11:00:57', NULL, 0, 'plain', '', 0, 0, 'info'),
(70, 'uk-vat-notice-2025-04-30', 'warning', 'en_US', 'UK VAT numbers are no longer supported', 'Due to recent HM Revenue &amp; Customs (HMRC) VAT API changes, your EU VAT Number for WooCommerce extension can no longer validate UK VAT numbers. HMRC now requires merchants to register an API key, which this extension does not currently support. We recommend EU/UK VAT Validation Manager for WooCommerce as a replacement', '{}', 'pending', 'woocommerce.com', '2025-05-08 11:05:09', NULL, 0, 'plain', '', 0, 0, 'info'),
(71, 'payson-retirement-2025', 'update', 'en_US', 'Payson Form Retirement', 'Svea Bank is discontinuing the Payson service; the last date for transactions is August 31, 2025. As a result, the Payson Form extension has been removed from WooCommerce.com. Documentation remains available.', '{}', 'pending', 'woocommerce.com', '2025-05-15 15:53:53', NULL, 0, 'plain', '', 0, 0, 'info'),
(72, 'wc-admin-manage-orders-on-the-go', 'info', 'en_US', 'Gérez vos commandes à la volée', 'Recherchez des commandes et des informations sur les clients, et effectuez des remboursements en un clic à l’aide de l’application Woo.', '{}', 'unactioned', 'woocommerce-admin', '2025-11-03 07:41:31', NULL, 0, 'plain', '', 0, 0, 'info'),
(73, 'paypal-braintree-sdk-depreciation-2025-05-30', 'update', 'en_US', 'Action required: Update the PayPal Braintree extension', 'Your PayPal Braintree extension is using an outdated SDK and will stop processing payments after June 30, 2025, due to a root SSL certificate expiration. To avoid service disruption, update to version 3.2.4 or newer immediately.', '{}', 'pending', 'woocommerce.com', '2025-11-03 07:41:35', NULL, 0, 'plain', '', 0, 0, 'info'),
(74, 'wc-admin-performance-on-mobile', 'info', 'en_US', 'Suivre les performances de votre boutique sur mobile', 'Suivez vos ventes et performances de vos produits avec l’application Woo.', '{}', 'unactioned', 'woocommerce-admin', '2026-01-20 15:26:55', NULL, 0, 'plain', '', 0, 0, 'info'),
(75, 'paypal-carding-recaptcha-dec-25', 'update', 'en_US', 'Activate PayPal fraud management', 'PayPal detected increased suspicious card activity in market. Please enable fraud protection in your PayPal Payment settings by enabling CAPTCHA for PayPal Payments.', '{}', 'pending', 'woocommerce.com', '2026-01-20 15:26:57', NULL, 0, 'plain', '', 0, 0, 'info'),
(76, 'paypal-carding-recaptcha-jan-26', 'update', 'en_US', 'Fraud protection is now required — enable today', 'Card networks like Visa and Mastercard now require fraud prevention controls, and non-compliance may result in fines and processing restrictions. Please enable reCAPTCHA in your PayPal Payments settings to help protect your store and maintain compliance.', '{}', 'pending', 'woocommerce.com', '2026-01-20 15:26:57', NULL, 0, 'plain', '', 0, 0, 'info'),
(77, 'existing_square_bitcoin_promotion_q1_2026', 'marketing', 'en_US', 'Take bitcoin payments in Square with 0% fees in 2026', 'Your Square POS can now accept in-person bitcoin payments, with near-instant settlement and no chargebacks. Enable it today and pay zero fees through 2026. T&amp;Cs apply.', '{}', 'pending', 'woocommerce.com', '2026-01-22 15:31:18', NULL, 0, 'plain', '', 0, 0, 'info'),
(78, 'prospects_square_bitcoin_promotion_q1_2026', 'marketing', 'en_US', 'Take bitcoin payments in Square with 0% fees in 2026', 'Accept in-person <a href=\"https://woocommerce.com/posts/square-bitcoin-launch\">bitcoin payments</a> with Square POS — and pay zero fees on all bitcoin transactions through 2026. Get near-instant settlement and total protection from chargebacks.', '{}', 'pending', 'woocommerce.com', '2026-01-22 15:31:18', NULL, 0, 'plain', '', 0, 0, 'info'),
(79, 'wc-admin-orders-milestone', 'info', 'en_US', 'Première commande reçue', 'Félicitations pour votre première commande ! C’est le moment idéal pour apprendre à gérer vos commandes.', '{\"current_milestone\":1}', 'unactioned', 'woocommerce-admin', '2026-01-31 21:50:55', NULL, 0, 'plain', '', 0, 0, 'info'),
(80, 'wc-admin-edit-products-on-the-move', 'info', 'en_US', 'Modifier les produits en étant mobile', 'Modifier et créer des nouveaux produits depuis votre application mobile avec l’application WooCommerce', '{}', 'unactioned', 'woocommerce-admin', '2026-04-27 11:35:55', NULL, 0, 'plain', '', 0, 0, 'info'),
(81, 'wc-admin-launch-checklist', 'info', 'en_US', 'Prêt à lancer votre boutique ?', 'Pour ne jamais ressentir cette sensation d’avoir oublié quelque chose, nous avons conçu une liste de contrôle reprenant les points essentiels avant lancement.', '{}', 'unactioned', 'woocommerce-admin', '2026-04-27 11:35:55', NULL, 0, 'plain', '', 0, 0, 'info'),
(82, 'stripe-woo-gateway-update-april2026', 'update', 'en_US', 'A critical update is required for Stripe for WooCommerce', '<strong>A critical update is required for Stripe for WooCommerce</strong> that addresses possible payment issues. Please update the WooCommerce Stripe Gateway to v10.6.1 immediately.', '{}', 'pending', 'woocommerce.com', '2026-04-27 11:36:03', NULL, 0, 'plain', '', 0, 0, 'info'),
(83, 'klaviyo_q2_2026', 'marketing', 'en_US', 'Attn Woo: Klaviyo Customer Hub is here', 'Drive revenue and reduce your support burden by giving customers a single place to manage their orders, returns, subscriptions, loyalty, and more. Enable Customer Hub in your Klaviyo dashboard today, available on all paid plans.', '{}', 'pending', 'woocommerce.com', '2026-05-08 20:41:48', NULL, 0, 'plain', '', 0, 0, 'info'),
(84, 'existing_square_discountcodes_gtm_q2_2026', 'marketing', 'en_US', 'Automatic coupon sync now available in Square', 'The discount codes you create in your Square dashboard will now work directly on your WooCommerce checkout — no need to manually sync coupons. Manage all of your discounts from one place with automatic redemption count updates.', '{}', 'pending', 'woocommerce.com', '2026-05-15 08:13:26', NULL, 0, 'plain', '', 0, 0, 'info'),
(85, 'prospects_square_discountcodes_gtm_q2_2026', 'marketing', 'en_US', 'Square now offers automatic coupon sync', 'Big news for smoother cross-channel sales: you can now create discount codes in Square and have them work directly at checkout on your Woo store, no manual sync required. Save time when you manage your discounts from one place — and keep your online and in-person sales seamlessly connected.', '{}', 'pending', 'woocommerce.com', '2026-05-18 15:19:04', NULL, 0, 'plain', '', 0, 0, 'info'),
(86, 'paypal_bnpl_mx_promo_Q2_2026', 'marketing', 'en_US', 'Bigger carts, lower fees: enable installments today', 'Merchants using PayPal installments see up to 205% higher average order values. Activate 3-installment payments from your PayPal Business dashboard and get 30% off transaction fees for 90 days. Sign up by October 15, 2026. Limited availability. Terms apply.', '{}', 'pending', 'woocommerce.com', '2026-05-20 14:53:00', NULL, 0, 'plain', '', 0, 0, 'info'),
(87, 'stripe_adaptivepricing_q2_2026', 'marketing', 'en_US', 'Sell internationally with Adaptive Pricing from Stripe', 'Adaptive Pricing is now available in the official Stripe for WooCommerce extension. Show prices in local currency across 150+ countries, lifting cross-border revenue by 17.8%. Shoppers pay exactly what they see at checkout, while you settle in your base currency.', '{}', 'pending', 'woocommerce.com', '2026-06-03 09:33:50', NULL, 0, 'plain', '', 0, 0, 'info'),
(88, 'woo-dotcom-course-2026-06-09', 'marketing', 'en_US', 'Learn how to build your store with WooCommerce', 'In this free course, we\'ll help you set up and run your online store with clear, practical guidance.', '{}', 'pending', 'woocommerce.com', '2026-06-22 15:44:07', NULL, 0, 'plain', '', 0, 0, 'info'),
(89, 'APFS-consolidation-jun-26', 'marketing', 'en_US', 'New features in WooCommerce Subscriptions', 'All Products for WooCommerce Subscriptions is now included in WooCommerce Subscriptions — no extra extension required. Create multiple plans for a single product and turn one-time purchases into recurring revenue. Update Subscriptions to version 9.0 to get started.', '{}', 'pending', 'woocommerce.com', '2026-06-24 15:19:59', NULL, 0, 'plain', '', 0, 0, 'info');
