(2313, 69, 'klaviyo_q2_2025', 'Try Klaviyo today', 'https://woocommerce.com/products/klaviyo-for-woocommerce/?utm_source=inbox_note&utm_medium=product&utm_campaign=klaviyo_q2_2025', 'actioned', '', NULL, NULL),
(2319, 2, 'wayflyer_bnpl_q4_2021', 'Level up with funding', 'https://woocommerce.com/products/wayflyer/?utm_source=inbox_note&utm_medium=product&utm_campaign=wayflyer_bnpl_q4_2021', 'actioned', '', NULL, NULL),
(2320, 3, 'wc_shipping_mobile_app_usps_q4_2021', 'Get WooCommerce Shipping', 'https://woocommerce.com/woocommerce-shipping/?utm_source=inbox_note&utm_medium=product&utm_campaign=wc_shipping_mobile_app_usps_q4_2021', 'actioned', '', NULL, NULL),
